def create_authors_from_existing_names(apps, schema_editor):
    Autor = apps.get_model('catalogo', 'Autor')
    Libro = apps.get_model('catalogo', 'Libro')
    database = schema_editor.connection.alias

    for libro in Libro.objects.using(database).all().iterator():
        nombre_completo = (libro.autor or '').strip()
        partes = nombre_completo.rsplit(maxsplit=1)
        if len(partes) == 2:
            nombre, apellido = partes
        else:
            nombre, apellido = nombre_completo, ''

        autor, _ = Autor.objects.using(database).get_or_create(
            nombre=nombre,
            apellido=apellido,
        )
        Libro.objects.using(database).filter(pk=libro.pk).update(
            autor=str(autor.pk),
        )


def restore_author_names(apps, schema_editor):
    Libro = apps.get_model('catalogo', 'Libro')
    database = schema_editor.connection.alias

    for libro in Libro.objects.using(database).select_related('autor').iterator():
        autor = libro.autor
        if autor is not None:
            nombre_completo = ' '.join(
                parte for parte in (autor.nombre, autor.apellido) if parte
            )
            Libro.objects.using(database).filter(pk=libro.pk).update(
                autor=nombre_completo,
            )


